def point(cam,u,v,o=None):
 o=o or load(); cam='robot0_'+cam if not cam.startswith('robot') else cam
 d=o.depth[cam];d=d[-1] if d.ndim==3 else d;z=float(d[v,u]);c=o.meta['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);p=T@np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);return p[:3]
def ik(p,R=None,q=None):
 s=state();q=s[4:11] if q is None else np.array(q);origin=np.load(OUT+'/arm_origin.npy');
 def fun(x):
  T=fk(x);err=(T[:3,3]+origin-p)*5
  if R is not None:err=np.r_[err,Rot.from_matrix(R@T[:3,:3].T).as_rotvec()]
  return np.r_[err,.015*(x-q)]
 sol=least_squares(fun,q,bounds=([-2.89,-1.76,-2.89,-3.06,-2.89,-.01,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89]),max_nfev=300)
 print('ik error',fun(sol.x)[:6]);return sol.x
def move(p,R=None,n=50,grip=None,label='move'):
 return run(ik(np.array(p),R),grip=grip,n=n,label=label)
PY
